308	  override runObject(): void {
309	    const ctx = this._context;
310	    if (!ctx?.scene) return;
311	
312	    const root = this.ensureTimelineRoot("jetEngineRoot");
313	    if (!root) return;
314	    this._cfg = JetEngine.resolveConfig(this._options);
315	    this._intensity = Math.max(0, Math.min(1, this._cfg.baseIdle));
316	    this._sim.applyConfig(this._cfg);
317	    this._build();
318	
319	    const attachTo = this._options.attachTo;
320	    const offset = this._options.offset ?? { x: 0, y: 0, z: 0 };
321	    const p = this._options.position ?? { x: 0, y: 0, z: 0 };
322	    const r = this._options.rotation ?? { x: 0, y: 0, z: 0 };
323	    const s = this._options.scale ?? { x: 1, y: 1, z: 1 };
324	
325	    if (attachTo && typeof ctx.getObject === "function") {
326	      const target = ctx.getObject(attachTo);
327	      if (target instanceof THREE.Object3D) {
328	        target.add(root);
329	        root.position.set(offset.x ?? 0, offset.y ?? 0, offset.z ?? 0);
330	      } else {
331	        root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
332	      }
333	    } else {
334	      root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
335	    }
336	
337	    Helpers.applyRotationDeg(root, r);
338	    root.scale.set(s.x ?? 1, s.y ?? 1, s.z ?? 1);
339	    root.traverse((child) => {
340	      child.layers.set(THREE_LAYER_ROCKET);
341	    });
342	    this._built = true;
343	  }
