399	  private _build(): void {
400	    const root = this.getTimelineRoot();
401	    if (!root) return;
402	    const shaderOwnerId = this.getShaderOwnerId();
403	    this.releaseShaders(shaderOwnerId);
404	    this._teardown();
405	    const cfg = this._cfg;
406	    const nr = cfg.nozzleRadius;
407	    const gridStepX = nr * Math.max(0.2, cfg.nozzleGapX);
408	    const gridStepZ = nr * Math.max(0.2, cfg.nozzleGapZ);
409	    const tipY = -(cfg.baseLength * 0.85);
410	    const parentR = Math.max(gridStepX, gridStepZ) * 1.9 + nr;
411	    const innerVert = JetEngine.innerVertGLSL(cfg);
412	    const innerFrag = JetEngine.innerFragGLSL(cfg);
413	    const parentVert = JetEngine.parentVertGLSL(cfg);
414	    const parentFrag = JetEngine.parentFragGLSL(cfg);
415	
416	    const layout: ReadonlyArray<readonly [number, number]> = [
417	      [-1, 2],
418	      [0, 2],
419	      [1, 2],
420	      [-0.5, 1],
421	      [0.5, 1],
422	      [-1, 0],
423	      [0, 0],
424	      [1, 0],
425	      [-0.5, -1],
426	      [0.5, -1],
427	      [-1, -2],
428	      [0, -2],
429	      [1, -2],
430	    ];
431	
432	    layout.forEach(([gx, gz], i) => {
433	      const pos = new THREE.Vector3(gx * gridStepX, 0, gz * gridStepZ);
434	      const isCenter = gx === 0 && gz === 0;
435	      if (!this._innerGeo) {
436	        this._innerGeo = new THREE.CylinderGeometry(0.004, nr, 1.0, 24, 20, true);
437	      }
438	      const geo = this._innerGeo;
439	      const mat = new THREE.ShaderMaterial({
440	        uniforms: {
441	          uTime: { value: 0 },
442	          uFlameLen: { value: 1 },
443	          uThrottle: { value: 1 },
444	          uSeed: { value: i * 2.71828 + 0.5 },
445	        },
446	        vertexShader: innerVert,
447	        fragmentShader: innerFrag,
448	        transparent: true,
449	        side: THREE.DoubleSide,
450	        depthWrite: false,
451	        blending: THREE.AdditiveBlending,
452	      });
453	      this.registerShader({
454	        key: this.createShaderKey(`inner.${i}`),
455	        ownerId: shaderOwnerId,
456	        material: mat,
457	        autoResolution: false,
458	      });
459	      const mesh = new THREE.Mesh(geo, mat);
460	      mesh.rotation.x = Math.PI;
461	      mesh.position.y = -0.5;
462	      mesh.layers.set(THREE_LAYER_ROCKET);
463	      mesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
464	      const group = new THREE.Group();
465	      group.add(mesh);
466	      group.position.copy(pos);
467	      if (!isCenter) {
468	        const dir = new THREE.Vector3(0, tipY, 0).sub(pos).normalize();
469	        group.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);
470	      }
471	      root.add(group);
472	      const blooms = this._buildBlooms(group, [
473	        {
474	          color: [0.3, 0.6, 1.0],
475	          radius: 6.0,
476	          size: nr * 5,
477	          baseI: 0.55,
478	          y: -0.05,
479	        },
480	        {
481	          color: [0.15, 0.4, 1.0],
482	          radius: 2.5,
483	          size: nr * 10,
484	          baseI: 0.35,
485	          y: -0.35,
486	        },
487	      ]);
488	      if (isCenter) {
489	        blooms.push(
490	          ...this._buildBlooms(group, [
491	            {
492	              color: cfg.innerColor.top,
493	              radius: 6.8,
494	              size: nr * 10.5,
495	              baseI: 0.42,
496	              y: 0.04,
497	            },
498	          ]),
499	        );
500	      }
501	      this._inner.push({ group, mat, blooms });
502	    });
503	
504	    const pGeo = new THREE.CylinderGeometry(0.01, parentR, 1.0, 40, 28, true);
505	    const pMat = new THREE.ShaderMaterial({
506	      uniforms: {
507	        uTime: { value: 0 },
508	        uFlameLen: { value: 1 },
509	        uThrottle: { value: 1 },
510	        uSeed: { value: 99.9 },
511	      },
512	      vertexShader: parentVert,
513	      fragmentShader: parentFrag,
514	      transparent: true,
515	      side: THREE.DoubleSide,
516	      depthWrite: false,
517	      blending: THREE.AdditiveBlending,
518	    });
519	    this.registerShader({
520	      key: this.createShaderKey("parent"),
521	      ownerId: shaderOwnerId,
522	      material: pMat,
523	      autoResolution: false,
524	    });
525	    const pMesh = new THREE.Mesh(pGeo, pMat);
526	    pMesh.rotation.x = Math.PI;
527	    pMesh.position.y = -0.5;
528	    pMesh.layers.set(THREE_LAYER_ROCKET);
529	    pMesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
530	    const pGroup = new THREE.Group();
531	    pGroup.add(pMesh);
532	    root.add(pGroup);
533	    const pBlooms = this._buildBlooms(pGroup, [
534	      {
535	        color: [1.0, 0.95, 0.85],
536	        radius: 5.0,
537	        size: parentR * 4.5,
538	        baseI: 0.22,
539	        y: -0.05,
540	      },
541	      {
542	        color: [0.9, 0.95, 1.0],
543	        radius: 2.0,
544	        size: parentR * 7.0,
545	        baseI: 0.14,
546	        y: -0.4,
547	      },
548	    ]);
549	    this._parent = { group: pGroup, mat: pMat, blooms: pBlooms };
550	  }
551	
552	  private _teardown(): void {
553	    this._innerGeo?.dispose();
554	    this._innerGeo = null;
555	    for (const eng of this._inner) {
556	      eng.group.traverse((obj) => {
557	        if (obj instanceof THREE.Mesh) {
558	          (obj.material as THREE.Material).dispose();
559	        }
560	      });
561	      for (const b of eng.blooms) {
562	        b.mesh.geometry.dispose();
563	        b.mat.dispose();
564	      }
565	      eng.group.parent?.remove(eng.group);
566	    }
